const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var canberra = ee.Geometry.Point([149.1300, -35.2809]); // Canberra coordinates
  var startDate = '2020-01-14';
  var endDate = '2020-01-22';

  // 2. Data Acquisition - GPM precipitation data
  var precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .filterBounds(canberra);

  var colSize = precipCol.size().getInfo();
  print(`GPM Images found: ${colSize}`);

  if (colSize === 0) {
    print("No precipitation data found for the period.");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over the period
  var totalPrecip = precipCol.select('precipitationCal').sum();

  // 4. Calculate total rainfall in the area
  var stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: canberra,
    scale: 10000,
    maxPixels: 1e9
  });

  var meanPrecip = stats.get('precipitationCal');

  // Get pixel count to check for valid data
  var countStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: canberra,
    scale: 10000,
    maxPixels: 1e9
  });

  var pixelCount = countStats.get('precipitationCal').getInfo();
  var precipValue = meanPrecip.getInfo();

  print(`Valid pixels: ${pixelCount}`);
  print(`Total precipitation (mm): ${precipValue ? precipValue.toFixed(2) : 'null'}`);

  if (pixelCount === 0) {
    print("No valid precipitation pixels.");
    print("<answer>C2</answer>");
    return;
  }

  if (precipValue === null || precipValue === undefined || isNaN(precipValue)) {
    print("Invalid precipitation calculation.");
    print("<answer>C3</answer>");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  var precipInches = precipValue / 25.4;
  print(`Total precipitation (inches): ${precipInches.toFixed(2)}`);

  // 5. Final Answer
  if (precipInches > 8) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
